// Synthetic, memory-backed logical I/O experiment; not physical SD or package ABI.
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <random>
#include <string>
#include <vector>
using U=uint64_t; using Clock=std::chrono::steady_clock;
struct R{U lo,hi,id,max;}; struct Q{U lo,hi;};
struct Store{std::vector<R> a;size_t page=128,last=SIZE_MAX;U reads=0,bytes=0;R get(size_t i){size_t p=i/page;if(p!=last){++reads;bytes+=std::min(page,a.size()-p*page)*sizeof(R);last=p;}return a[i];}};
struct E{U hz,end;}; struct Run{U hz,begin,end;};
struct Engine{
 Store s;std::vector<R> blocks;std::vector<U> tree;std::vector<E> sparse;std::vector<Run> dict;size_t stride;bool combined;
 Engine(const std::vector<R>& a,size_t p,size_t st,bool di,bool co=false):stride(st),combined(co){s.page=p;U mx=0;for(auto r:a){if(co||r.lo==r.hi){r.max=mx=std::max(mx,r.hi);s.a.push_back(r);}else blocks.push_back(r);}if(st)for(size_t i=0;i<s.a.size();i+=st){size_t e=std::min(i+st,s.a.size());sparse.push_back({s.a[e-1].lo,e});}if(di)for(size_t i=0;i<s.a.size();){size_t e=i+1;while(e<s.a.size()&&s.a[e].lo==s.a[i].lo)++e;dict.push_back({s.a[i].lo,i,e});i=e;}tree.resize(blocks.size()*4);if(!blocks.empty())build(1,0,blocks.size());}
 U build(size_t n,size_t l,size_t r){return tree[n]=r-l==1?blocks[l].hi:std::max(build(n*2,l,(l+r)/2),build(n*2+1,(l+r)/2,r));}
 template<class F>void intervals(size_t n,size_t l,size_t r,Q q,F& f){if(tree[n]<q.lo||blocks[l].lo>q.hi)return;if(r-l==1){f(blocks[l].id);return;}intervals(n*2,l,(l+r)/2,q,f);intervals(n*2+1,(l+r)/2,r,q,f);}
 template<class F>void query(Q q,F f){size_t l=0,r=s.a.size();if(!dict.empty()){auto it=std::lower_bound(dict.begin(),dict.end(),q.lo,[](Run x,U hz){return x.hz<hz;});for(;it!=dict.end()&&it->hz<=q.hi;++it)for(size_t i=it->begin;i<it->end;++i)f(s.get(i).id);}else{if(stride){auto it=std::lower_bound(sparse.begin(),sparse.end(),q.lo,[](E x,U hz){return x.hz<hz;});if(it==sparse.end())l=r;else{l=it==sparse.begin()?0:(it-1)->end;r=it->end;}}while(l<r){size_t m=l+(r-l)/2;auto x=s.get(m);if((combined?x.max:x.lo)<q.lo)l=m+1;else r=m;}for(;l<s.a.size();++l){auto x=s.get(l);if(x.lo>q.hi)break;if(x.hi>=q.lo)f(x.id);}}if(!blocks.empty())intervals(1,0,blocks.size(),q,f);}
 U mem()const{return blocks.capacity()*sizeof(R)+tree.capacity()*sizeof(U)+sparse.capacity()*sizeof(E)+dict.capacity()*sizeof(Run);}
};
std::vector<R> data(size_t n,bool stress){std::vector<R>a;std::mt19937_64 g(42);U id=0;for(size_t i=0;i<n;++i){U f=100000000+U(i)*25000;for(int j=0;j<10;++j)a.push_back({f,f,++id,0});}for(int i=0;i<2000;++i){U f=100000000+(g()%n)*25000;a.push_back({f,f+25000*(1+g()%8),++id,0});}if(stress)a.push_back({1,UINT64_MAX,++id,0});std::sort(a.begin(),a.end(),[](R x,R y){return x.lo!=y.lo?x.lo<y.lo:x.id<y.id;});return a;}
std::vector<Q> queries(size_t n,size_t u,int mode){std::vector<Q>v;std::mt19937_64 g(1234+mode);for(size_t i=0;i<n;++i){U k=mode==2?i%u:mode==3?i%32:g()%u;U f=100000000+k*25000;if(mode==1)f+=12500;v.push_back(mode==4?Q{f-1000,f+26000}:Q{f,f});}return v;}
void verify(Engine& e,const std::vector<R>&a,const std::vector<Q>&qs){for(auto q:qs){std::vector<U>x,y;for(auto r:a)if(r.lo<=q.hi&&r.hi>=q.lo)x.push_back(r.id);e.query(q,[&](U id){y.push_back(id);});std::sort(x.begin(),x.end());std::sort(y.begin(),y.end());if(x!=y){std::cerr<<"MISMATCH\n";std::exit(2);}}}
void bench(const std::string&name,Engine&e,const std::vector<Q>&qs,int mode,bool warm){std::vector<U>ns;ns.reserve(qs.size());U count=0,sum=0;e.s.last=SIZE_MAX;e.s.reads=e.s.bytes=0;auto start=Clock::now();for(auto q:qs){if(!warm)e.s.last=SIZE_MAX;auto a=Clock::now();e.query(q,[&](U id){++count;sum+=id;});ns.push_back(std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-a).count());}auto wall=std::chrono::duration_cast<std::chrono::nanoseconds>(Clock::now()-start).count();std::sort(ns.begin(),ns.end());auto p=[&](size_t x){return ns[(ns.size()-1)*x/100];};std::cout<<name<<','<<mode<<','<<warm<<','<<qs.size()<<','<<e.mem()<<','<<ns.front()<<','<<p(50)<<','<<p(90)<<','<<p(95)<<','<<p(99)<<','<<ns.back()<<','<<wall<<','<<e.s.reads<<','<<e.s.bytes<<','<<count<<','<<sum<<'\n';}
int main(int argc,char**argv){size_t u=argc>1?std::stoull(argv[1]):100000,n=argc>2?std::stoull(argv[2]):100000;if(u<32||n==0||u>1000000)return 1;auto a=data(u,false),small=data(256,true);std::vector<Q> check;for(int m=0;m<5;++m){auto q=queries(100,256,m);check.insert(check.end(),q.begin(),q.end());}check.insert(check.end(),{{0,0},{UINT64_MAX,UINT64_MAX},{0,UINT64_MAX},{100000000,100000000}});Engine p(small,128,0,false,true);verify(p,small,check);for(size_t page:{1,16,32,64,128,256,512,1024,2048}){Engine e(small,page,page==1?0:page,false);verify(e,small,check);}Engine d(small,128,0,true);verify(d,small,check);std::cerr<<"full-set oracle passed: 11 variants x 504 queries\n";std::cout<<"algorithm,mode,warm,queries,index_capacity_bytes,min_ns,p50_ns,p90_ns,p95_ns,p99_ns,max_ns,wall_ns,logical_reads,logical_bytes,result_count,id_sum\n";for(int m=0;m<5;++m){auto qs=queries(n,u,m);Engine b(a,1,0,false);bench("split_binary",b,qs,m,false);for(size_t page:{16,32,64,128,256,512,1024,2048}){Engine e(a,page,page,false);bench("sparse_"+std::to_string(page*32),e,qs,m,false);}Engine e(a,128,0,true);bench("dictionary",e,qs,m,false);bench("dictionary",e,qs,m,true);}auto stress=data(u,true);auto qs=queries(100,u,0);Engine c(stress,128,0,false,true);bench("combined_prefix_long",c,qs,5,false);Engine x(stress,128,128,false);bench("split_long",x,qs,5,false);}
